**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ifstream plik("liczby.txt");
    vector<int> tab;
    int x;
    while (plik >> x) tab.push_back(x);
    sort(tab.begin(), tab.end());
    int n = tab.size();

    int minRozn = tab[1] - tab[0];
    int idx = 0;
    for (int i = 1; i < n - 1; i++) {
        int r = tab[i + 1] - tab[i];
        if (r < minRozn) {
            minRozn = r;
            idx = i;
        }
    }

    cout << "Najblizsza para: " << tab[idx] << " i " << tab[idx + 1] << endl;
    cout << "Roznica: " << minRozn << endl;
    return 0;
}
```

**Wyjasnienie**: Po sortowaniu najblizsza para to zawsze para sasiadow. Wystarczy jeden przebieg po posortowanej tablicy sprawdzajac n-1 roznic.

Weryfikacja:
- Posortowane: 8, 15, 17, 29, 31, 42, 45, 56, 64, 73
- Roznice sasiadow: 7, 2, 12, 2, 11, 3, 11, 8, 9
- Min roznica: 2, pierwsza para: 15 i 17 (indeks 1 i 2 w posortowanej tablicy).
